package dev.blocklens.core.render;

/**
 * Clean-room decal glyphs drawn over the active block texture by the decoration renderers.
 *
 * <p>Each glyph is an original 32x32 white-on-transparent sprite generated by
 * {@code scripts/generate_decoration_glyphs.py}; the renderer tints it per semantic state.
 * Glyph "up" is texture row 0. Line work is two texels wide (one block unit).</p>
 */
public enum DecorationGlyph {
    /** Frame inset by one unit: axis end faces and per-face state outlines. */
    INSET_FRAME,
    /** Frame on the outermost unit: the slab face that meets the block boundary. */
    EDGE_FRAME,
    /** Two lines on the left and right edges; quarter turn 1 makes them horizontal. */
    RAILS,
    /** Arrow whose tip points to glyph up, with a dark contour for light textures. */
    ARROW,
    /** Edge frame plus a centered horizontal seam: double-slab side faces. */
    SEAM_FRAME,
    /** Edge frame plus inset frame: double-slab top and bottom faces. */
    DOUBLE_FRAME;

    public static final int PIXELS = 32;

    private final String texturePath = "block/cue/" + name().toLowerCase(java.util.Locale.ROOT);

    /** Sprite path inside the {@code blocklens} namespace of the block atlas. */
    public String texturePath() {
        return texturePath;
    }
}
